custom_css:
/*作者：lazyalie*/
/*作者有话说:禁二传二改商用。感谢帮助过我的老师们🥺🥺*/
/* 部分代码来自教程帖以及尾巴老师的拼好码，教程帖指路https://discord.com/channels/1291925535324110879/1380392618336194702;拼好码指路https://discord.com/channels/1291925535324110879/1422717884378910801 */
/*头图素材来自小红书:林羡*/
/* 此美化可在主题颜色那里自定义颜色，具体是什么颜色可以自行尝试 */



@import url("https://fontsapi.zeoseven.com/225/main/result.css");/* "Mizuki-Ming" */
@import url("https://fontsapi.zeoseven.com/379/main/result.css");/* "TW-Sung" */




/* =====全局控制===== */
:root {
  --全局字体:"Mizuki-Ming" ;
  --三元素字体:"TW-Sung" ;
  --头像大小: 38cqw;
  --头像上下:35%;
  --头像左右:20.5%;
  --头像显示区域:center 50%; /*改数字调整头像到你想看到的部位，感谢咩野老师的代码*/
  --模糊度: 5px;  
  --气泡宽度: 100%;
  --气泡间距: 70px;
  --气泡与输入框间距: 50px;
  --输入框内文字: "走向未知的麦田";

}
/* =====全局控制结束===== */



body {
    font-family: "Mizuki-Ming";
    font-weight: normal;
}



/* =====补丁部分===== */
div.inline-drawer-content {
  z-index: 2147483647 !important;
  position: relative !important; 
}

/*感谢咩野老师的全局阴影去除*/
body *:not(#send_form):not(#send_form *):not(.mes .avatar ):not(.mes .avatar  *):not(.mes .mes_reasoning_header ):not( 
.completion_prompt_manager_prompt):not( 
textarea):not(blockquote){
  box-shadow: none !important;
  border: none!important;
  filter: none!important;
}

/*========文本调节========*/
.mes .mes_text {
    /* 字符间距  */
    letter-spacing: 1.8px; 
    /*  行间距   */
    line-height: 1.5 ; 
  text-align: justify !important;  
  padding-left: 1px;
  padding-right: 1px;
}
/* 每个段落开头缩进字符 */
p {
  text-indent: 0em; 
}
/*=====全局抽屉=====*/
  body.no-blur .drawer-content.openDrawer{
backdrop-filter: blur(var(--模糊度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) !important; 
}
/*====顶栏====*/
#top-settings-holder .drawer-icon{
color: var(--SmartThemeBorderColor) !important;
    -webkit-text-stroke: 3px var(--SmartThemeBodyColor) !important;
    paint-order: stroke fill !important;
  font-size: 1.5em;
  opacity: 1;

}
/*====底栏====*/
#send_form [class*="fa-"] {
color: var(--SmartThemeBorderColor) !important;
    -webkit-text-stroke: 3px var(--SmartThemeBodyColor) !important;
    paint-order: stroke fill !important;
  font-size: 0.8em;
}
/* 感谢nini老师分享的隐藏输入框小黑点 */
#send_textarea {
    resize: none !important;
}

/* 感谢墨千尾老师的输入框内文字自定义 */
#nonQRFormItems {
  position: relative;
}
#send_textarea::placeholder {
  color: rgba(0, 0, 0, 0) !important;
  text-shadow: none !important;
}
#nonQRFormItems:has(#send_textarea:placeholder-shown)::before {
  content: var(--输入框内文字);
  left: 50%;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
  color: var(--SmartThemeBorderColor);
  font-style: normal;
  font-size: 0.5em;
  pointer-events: none;
  z-index: 10;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: calc(100% - 30px);
}
#send_textarea {
background: var(--SmartThemeBodyColor)!important;
  color: var(--SmartThemeBorderColor)!important;
    border-radius: 0 !important;    
    padding: 2px;
    margin: 2px 1px;
  box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3)!important;
}
/* 感谢nakari老师的悬浮底栏 */
#sheld, 
#chat {
    height: calc(102dvh + var(--bottomFormBlockSize));
    max-height: calc(102dvh + var(--bottomFormBlockSize));
}
#send_form {
    backdrop-filter: blur(var(--模糊度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) !important; 
    border: 1.5px solid  rgba(255, 255, 255, 0.2);
    width: 95%;
    display: flex !important;
    align-items: center !important;
    border-radius: 0px !important; 
    padding: 8px 15px !important; 
    box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3);
    transition: all 0.3s ease; 
}
/* 确保输入框固定在底部 */
#form_sheld {
    position: sticky;
    bottom: 90px;
    transition: transform 0.3s ease;
}
/* ====按钮图标类==== */
.menu_button,
.menu_button * {
  background: var(--SmartThemeBodyColor)!important;
  color: var(--SmartThemeBorderColor)!important;
    border-radius: 0 !important;
  border: none!important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3) !important;
    padding: 2px 5px !important;
}
.menu_button.redWarningBG,
.menu_button.red_button {
    color:  rgba(162, 162, 162, 1) !important;
}
.menu_button.world_set,
.menu_button.fav_on {
   color: rgba(149, 149, 149, 1) !important;
}
/*======复选框======*/
input[type="checkbox"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: 16px !important;
    height: 16px !important;
    border-radius: 0 !important;
    border: none !important;
    background: var(--SmartThemeBorderColor) !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.3) !important;
    cursor: pointer !important;
}

input[type="checkbox"]:checked {
    background: var(--SmartThemeBodyColor) !important;
}
/*感谢nakari老师的防误触*/
/* 取消label交互 */
.checkbox_label {
  pointer-events: none !important;
}
/* 恢复复选框交互 */
input[type="checkbox"] {
  pointer-events: auto !important;
}
/* =====滚动条和滑动条=====*/
/* 隐藏所有滚动条 */
::-webkit-scrollbar {
  display: none !important;
}
/* Firefox */
* {
  scrollbar-width: none !important;
}
/* ====角色和用户区域==== */
/* 收藏区左右滑动 - 感谢twelve老师 */
#HotSwapWrapper {
    overflow: hidden;
}
#HotSwapWrapper > div {
    display: flex;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: hidden;
    height: calc(var(--avatar-base-height) + 10px);
    &::-webkit-scrollbar { height: 5px }
    &::-webkit-scrollbar-thumb {
        background: var(--ui-color-sec);
        border-radius: 5px;
    }
}
body.big-avatars #HotSwapWrapper > div {
    height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + 10px);
}
.character_select.is_fav ,
.avatar-container.interactable.selected{
background: var(--SmartThemeBodyColor)!important;  
    border-radius: 0 !important;  
  color: var(--SmartThemeBorderColor)!important;
}
.character_select.is_fav .avatar  {  
    margin: 0 !important;
    padding: 0 !important;       
    outline: none !important;  
}

.character_select.is_fav .ch_name {
color: var(--SmartThemeBorderColor)!important;
}
/* =====预设部分===== */
ul#completion_prompt_manager_list.text_pole.ui-sortable {
    background: none!important;    
}
.completion_prompt_manager_prompt {
    padding: 8px 42px !important;
}
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled),
.completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) * {
    background: var(--SmartThemeBodyColor) !important;
    color: var(--SmartThemeBorderColor) !important;
    box-shadow: 2px 2px 4px rgba(0, 0, 0, 0.3)!important;
  border: none!important;
}
/* =====七七八八框框===== */
.height100p.wide100p.maximized_textarea {
background:transparent;
}
textarea:not(#send_textarea,.height100p.wide100p.maximized_textarea),
input[type="number"]{
background: var(--SmartThemeBorderColor)!important;
  color: var(--SmartThemeBodyColor)!important;
    border-radius: 0 !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
    padding: 8px 15px !important;
  margin-bottom: 7px;
}
.popup[open]::backdrop{
background: var(--SmartThemeBorderColor);
}
.text_pole,
select{
    background: transparent;
    margin: 5px;  
}
#user-settings-block h4,
.standoutHeader{
  background: var(--SmartThemeBodyColor)!important;
  color: var(--SmartThemeBorderColor)!important;
  padding: 12px 24px; 
}
/* 展开框框 */
.inline-drawer-header{
  background-image: none!important;
  background-color: none!important;
  padding: 12px 24px; 
  margin: 12px  12px;
}
/* 展开后 */
div.inline-drawer-content {
    background: transparent!important;     border: none !important;  
  background-image: none!important;
  background-color: none!important;
   padding: 8px;
  margin-top: 5px;
}
　
/* 设置，菜单区域 */
body.no-blur div#extensionsMenu.options-content{
    backdrop-filter: blur(var(--模糊度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) !important;    
  font-family: var(--全局字体)!important;
}
div#options.font-family-reset {
backdrop-filter: blur(var(--模糊度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) !important;  
  font-family: var(--全局字体)!important;
}
/* 合并世界信息/知识书相关元素的样式 */
span.select2-selection,
span#select2-world_editor-container.select2-selection__rendered, 
span#select2-world_info-container-choice-62yu-126.select2-selection__choice__display{
    background: var(--SmartThemeBorderColor)!important; 
    border-radius: 0 !important;    
}
/* ===对话区域=== */
/* 设置气泡整体布局 */
#chat{
background: none!important;
container-type: inline-size !important;
    container-name: chat !important;
  padding-bottom: var(--气泡与输入框间距);

}

.mes {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;    
    border-radius: 0px!important;
  border: none!important;
  margin-bottom: var(--气泡间距)!important;
  background: var(--SmartThemeChatTintColor)!important;

}
.mes .mesAvatarWrapper {
   width: 100% !important;
    order: 1 !important;
    margin-bottom:  calc(var(--头像大小) * 0.65) !important;    ;   
    position: relative;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: flex-start !important;
    gap: 1px !important;

  }

/* 消息块置于下方并占满宽度 */
.mes .mes_block {
    order: 2 !important;
    width: 100% !important;
    max-width: 100% !important;    
    z-index: 1 !important;
}

/* 头像样式 */
.mes .avatar {  
  width: var(--头像大小) !important;
  height: calc(var(--头像大小) * 1.1/1.6) !important; 
  position: absolute;
  top: var(--头像上下);     
  left: var(--头像左右);    
  z-index: 22;
  filter: grayscale(100%)!important;
  transform: none !important; 
  box-shadow: none!important;
  border: none!important;
}

/* 头像图片样式 */
.mes .avatar img {
  width: 100% !important;
  height: 100% !important;
  object-fit: cover;
  border-radius: inherit;
  object-position: var(--头像显示区域);  
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.5) !important;
  border: none!important;
  z-index: 25;
}

.mes .avatar::after {
  content: '';
  position: absolute;
  bottom: -28%;
  left: -27%;
  width: 257%;  
  height: auto;
  aspect-ratio: 300/108;
  background-image: url('https://iili.io/qBcE08b.png');
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  z-index: 20;
  pointer-events: none;
  transform: translateX(-10%);  /* 微调水平位置 */
}

/*感谢nakari老师分享的最后一条消息与下方区域距离保持一致代码*/
/* 通用CSS */
.mes .mes_timer:empty,
.mes .mesIDDisplay:empty,
.mes .tokenCounterDisplay:empty {
    display: none;
}
.last_mes .mesAvatarWrapper {
    padding-bottom: 0px; 
}

/* 气泡主体样式 */
.mes .mes_block {
    background: var(--SmartThemeBotMesBlurTintColor);
    backdrop-filter: blur(var(--模糊度)) !important; 
    -webkit-backdrop-filter: blur(var(--模糊度)) !important; 
    border-radius: 0px !important; 
    width: var(--气泡宽度) !important;
    max-width: none !important; 
    padding: 15px !important;
    position: relative !important;
    margin-top: 0 !important; 
}


/* 楼层样式  */
.mes .mesIDDisplay {
    color: #ffffff;
    opacity: 1;
    font-size: 6cqw;
    font-weight: bold !important;      position: relative !important;
  transform: translateY(-8px) !important;
-webkit-text-stroke: 2px #000 !important;
paint-order: stroke fill !important;

}

.mes .mesIDDisplay::before {
    content: "第" !important;
    font-weight: normal !important;
    margin-right: 2px !important;
}

.mes .mesIDDisplay::after {
    content: "章" !important;
    font-weight: normal !important;
    margin-left: 2px !important;
}

/* 时间样式 */
.mes .mes_timer {
    font-size: 2cqw!important;
    position: relative !important;

    color: #000000;
}

.mes .mes_timer::before {
    content: "还需" !important;
    font-weight: normal !important;
    margin-right: 2px !important;
}

/* 字符数样式 */
.mes .tokenCounterDisplay {
    font-size: 2cqw!important;
    position: relative !important;
    color: #000000;
}

.mes .tokenCounterDisplay::before {
    content: "可解锁" !important;
    font-weight: normal !important;
    margin-right: 4px !important;
}

.mes .tokenCounterDisplay::after {
    content: "章" !important;
    font-weight: normal !important;
    margin-left: 2px !important;
}

.mes .mesIDDisplay {
  font-family: var(--三元素字体);
    position: relative !important;
    top: calc(var(--头像大小) * 0.62) !important;
    left: calc(var(--头像大小) * 0.52) !important;
   z-index: 35 !important;
}
.mes .mes_timer,
.mes .tokenCounterDisplay
{
  font-family: var(--三元素字体);
    position: relative !important;
    top: calc(var(--头像大小) * 0.62) !important;
    left: calc(var(--头像大小) * 1.2) !important;
   z-index: 35 !important;
  }


#chat .mes .mes_block .flex-container.alignItemsBaseline{
    position: absolute !important;
   bottom: -55px;
    left: 0 !important;
    right: 0 !important;
    width: 100% !important;
    background: var(--SmartThemeBotMesBlurTintColor) !important;
    border-radius: 0 !important;
    padding: 15px 15px !important;
    display: flex !important;
    flex-direction: row !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 8px !important;
    z-index: 5 !important;
}

.mes .flex-container.alignItemsBaseline::before,
.mes .flex-container.alignItemsBaseline::after {
    content: "" !important;
    flex: 1 !important;
    height: 1px !important;
    background: var(--SmartThemeUserMesBlurTintColor) !important;
    min-width: 10px !important;
}

.mes .mes_block {
    position: relative !important;
    margin-bottom: 90px !important;
    overflow: visible !important;
}

.mes .flex-container.alignItemsBaseline .ch_name::before,
.mes .flex-container.alignItemsBaseline .name_text::before {
    content: "◉ 玩家:" !important;
    font-size: 0.9em !important;
    margin-right: 2px !important;

}
.ch_name{
  font-size: 0.9em !important;
  font-weight: 400;
}
.mes .timestamp::before {
    content: "注册时间:" !important;    
    margin-right: 2px !important;
}
.mes .timestamp::after {
    content: " ◉" !important;    
    margin-right: 2px !important;
}
.mes .timestamp{
  opacity: 1;
  font-size: 0.9em !important;
}

/*n师给我的简易版移动左右箭头😋*/
/* 左切换箭头 */
.swipe_left {
  left: auto;
  bottom: 5px; /* 调整上下 */
  left:10px; /* 调整左右 */
  background: var(--SmartThemeBotMesBlurTintColor) !important;
    border-radius: 0 !important;
    font-size: 0 !important; 
  opacity: 1;
display: block !important;        
   width: 39px !important;
    height: 26px !important;
}


/* 消息数 */
.swipes-counter {
  transform:translateX(-450%) translateY(40%); 
  z-index: 50;
  font-size: 0.8em;
  color: var(--SmartThemeBodyColor);
  opacity: 1;
}
/* 右切换箭头 */
.swipeRightBlock {
  margin-right: 5px; /* 调整左右 */
  margin-bottom: 12px; /* 调整上下 */

}
.swipe_right {
  position: absolute;
  background: var(--SmartThemeBotMesBlurTintColor) !important;
    border-radius: 0 !important;
    font-size: 0 !important; 
  opacity: 1!important;
display: block !important;        
   width: 39px !important;
    height: 26px !important;
   opacity: 1;  
}
.swipe_left::after {
    content: "回溯";
  color: var(--SmartThemeBodyColor);
    position: absolute;
    bottom: 7px;
   left: 50%;
   transform: translateX(-50%);
    font-size: 14px;
    font-weight: bold;
  white-space: nowrap; 
}

.swipe_right::after {
    content: "启程";
     color: var(--SmartThemeBodyColor);
    position: absolute;
    bottom: 7px;
   left: 50%;
   transform: translateX(-50%);
    font-size: 14px;
    font-weight: bold;
  white-space: nowrap; 
}
/* =====思维链===== */
/* 思维链头部 */
.mes .mes_reasoning_header {
    background: rgba(255, 255, 255, 1) !important;
  color:#000000;
    border-radius: 0 !important;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
    padding: 8px 15px !important;
  transform: translateY(-25px) !important;  
}
.mes .mes_reasoning_arrow {
    display: none !important;
}
.mes .mes_reasoning_header_title {
    font-size: 0 !important;
}

.mes .mes_reasoning_header_title::after {
    content: "开始游戏" !important;
    font-size: 14px !important;
}

/* 展开后的内容区域 */
.mes .mes_reasoning {
    background: transparent !important;
    max-height: 200px !important;
    overflow-y: auto !important;
    border-left: none !important;
}

.mes .mes_reasoning::-webkit-scrollbar {
    display: none !important;

}

.mes .mes_reasoning::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2) !important;
    border-radius: 2px !important;
}

.mes .mes_reasoning::-webkit-scrollbar-track {
    background: transparent !important;
}

/* 文本美化 */
q{
  font-weight: 600;
}
pre code, 
code:not(pre code.hljs){
background: var(--SmartThemeBodyColor)!important;
  color: var(--SmartThemeBorderColor)!important;
    border-radius: 0 !important; 

}
blockquote{
  background: rgba(255, 255, 255, 1) !important;
  color:#000000;
  box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2) !important;
}
